<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><h1 class="h3 mb-4">Customers</h1><form class="card border-0 p-3 mb-4" method="get"><div class="row g-2"><div class="col-md-7"><input class="form-control" name="q" value="<?= esc($q) ?>" placeholder="Search name, mobile, or customer code"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['active','inactive','blocked'] as $option): ?><option value="<?= $option ?>" <?= $status===$option?'selected':'' ?>><?= ucfirst($option) ?></option><?php endforeach ?></select></div><div class="col-md-2"><button class="btn btn-success w-100">Filter</button></div></div></form><div class="card border-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Customer Code</th><th>Name</th><th>Mobile</th><th>Email</th><th>Status</th><th>Registered Date</th><th>Action</th></tr></thead><tbody><?php foreach($customers as $row): ?><tr><td><?= esc($row['customer_code']) ?></td><td><?= esc($row['full_name']) ?></td><td><?= esc($row['mobile']) ?></td><td><?= esc($row['email'] ?: '—') ?></td><td><?= esc(ucfirst($row['status'])) ?></td><td><?= esc($row['created_at']) ?></td><td><a class="btn btn-sm btn-outline-success" href="<?= url_to('admin.customer.show',$row['id']) ?>">View</a></td></tr><?php endforeach ?><?php if(!$customers): ?><tr><td colspan="7" class="text-center text-muted">No customers found.</td></tr><?php endif ?></tbody></table></div></div><div class="mt-3"><?= $pager->links() ?></div><?= $this->endSection() ?>
